'use client';
import { FormEvent, useEffect, useMemo, useState } from 'react';
import VendorShell from '../../components/VendorShell';
import { api } from '../../lib/api';
const money=(k:number)=>`₦${(Math.round(k)/100).toLocaleString('en-NG',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
type Tab='overview'|'earnings'|'transactions'|'payouts'|'account';
export default function FinancePage(){
 const [tab,setTab]=useState<Tab>('overview'),[range,setRange]=useState('30'),[overview,setOverview]=useState<any>(null),[rows,setRows]=useState<any[]>([]),[payouts,setPayouts]=useState<any[]>([]),[account,setAccount]=useState<any>(null),[error,setError]=useState(''),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[form,setForm]=useState({bankName:'',bankCode:'',accountName:'',accountNumber:''});
 const dates=useMemo(()=>{const to=new Date(),from=new Date();from.setDate(to.getDate()-Number(range));return `from=${encodeURIComponent(from.toISOString())}&to=${encodeURIComponent(to.toISOString())}`},[range]);
 async function load(){setLoading(true);setError('');try{const[o,a,p]=await Promise.all([api(`/api/vendor/finance/overview?${dates}`),api('/api/vendor/finance/payment-account'),api('/api/vendor/finance/payouts')]);setOverview(o);setAccount(a);setPayouts(p);if(a)setForm({bankName:a.bankName,bankCode:a.bankCode||'',accountName:a.accountName,accountNumber:''});if(tab==='earnings')setRows(await api(`/api/vendor/finance/earnings?${dates}`));if(tab==='transactions')setRows(await api(`/api/vendor/finance/transactions?${dates}`));}catch(e:any){setError(e.message||'Unable to load finance data.')}finally{setLoading(false)}}
 useEffect(()=>{load()},[range,tab]);
 async function save(e:FormEvent){e.preventDefault();setSaving(true);setError('');try{if(!/^\d{10}$/.test(form.accountNumber))throw Error('Enter the full 10-digit bank account number.');const a=await api('/api/vendor/finance/payment-account',{method:'POST',body:JSON.stringify(form)});setAccount(a);setForm({...form,accountNumber:''})}catch(e:any){setError(e.message||'Could not save payout account.')}finally{setSaving(false)}}
 const tabs:[Tab,string,string][]=[['overview','Overview','Your money at a glance'],['earnings','Earnings','Order-level earnings'],['transactions','Transactions','Ledger activity'],['payouts','Payouts','Settlement history'],['account','Payment account','Bank & payout details']];
 return <VendorShell><div className="finance-page"><div className="finance-heading"><div><span className="finance-eyebrow">Business · Finance</span><h1>Finance</h1><p>Track earnings, deductions, payouts and your settlement account.</p></div><select value={range} onChange={e=>setRange(e.target.value)}><option value="0">Today</option><option value="7">Last 7 days</option><option value="30">Last 30 days</option><option value="90">Last 90 days</option></select></div>{error&&<div className="finance-alert">{error}</div>}<div className="finance-tabs">{tabs.map(([id,label,sub])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}><strong>{label}</strong><small>{sub}</small></button>)}</div>{loading?<div className="finance-state"><div className="finance-spinner"/><strong>Loading finance</strong><span>Getting the latest ledger information…</span></div>:tab==='overview'&&overview?<Overview d={overview}/>:tab==='earnings'?<Earnings rows={rows}/>:tab==='transactions'?<Transactions rows={rows}/>:tab==='payouts'?<Payouts rows={payouts}/>:<Account a={account} f={form} setF={setForm} save={save} saving={saving}/>}</div></VendorShell>}
function Overview({d}:any){return <div className="finance-content"><div className="finance-balance-grid"><Balance t="Available balance" v={d.availableBalance} hi/><Balance t="Pending balance" v={d.pendingBalance} n={`${d.pendingOrderCount} order${d.pendingOrderCount===1?'':'s'} in progress`}/><Balance t="Total earnings" v={d.vendorEarnings}/><Balance t="Paid out" v={d.paidOut}/></div><div className="finance-grid-2"><section className="finance-card"><Head s="Performance" t="Settlement breakdown"/><div className="finance-breakdown"><M t="Gross product sales" v={money(d.grossSales)}/><M t="ROZZI commission" v={`− ${money(d.commission)}`}/><M t="Discounts" v={`− ${money(d.discounts)}`}/><M t="Vendor earnings" v={money(d.vendorEarnings)} hi/><M t="Delivery fees" v={money(d.deliveryFees)}/><M t="Average order" v={money(d.averageOrderValue)}/></div></section><section className="finance-card"><Head s="Payment account" t={d.paymentAccount?.bankName||'Not connected'}/>{d.paymentAccount?<div className="bank-summary"><strong>{d.paymentAccount.accountName}</strong><span>•••• {d.paymentAccount.accountNumberLast4}</span><small>{d.paymentAccount.payoutMethod.replace('_',' ')}</small></div>:<p className="finance-muted">Add a bank account before payouts can be prepared for settlement.</p>}</section></div><section className="finance-card"><Head s="Recent activity" t="Latest transactions"/><TransactionTable rows={d.recentTransactions}/></section></div>}
function Balance({t,v,n,hi}:{t:string;v:number;n?:string;hi?:boolean}){return <div className={`finance-balance ${hi?'emphasis':''}`}><span>{t}</span><strong>{money(v)}</strong>{n&&<small>{n}</small>}</div>};function Head({s,t}:{s:string;t:string}){return <div className="finance-card-head"><div><span>{s}</span><h2>{t}</h2></div></div>};function M({t,v,hi}:{t:string;v:string;hi?:boolean}){return <div><span>{t}</span><strong className={hi?'highlight':''}>{v}</strong></div>}
function Earnings({rows}:any){return <div className="finance-content"><section className="finance-card"><Head s="Order earnings" t="Delivered order breakdown"/><div className="finance-table-wrap"><table className="finance-table"><thead><tr><th>Order</th><th>Date</th><th>Sales</th><th>Commission</th><th>Vendor earning</th></tr></thead><tbody>{rows.map((r:any)=><tr key={r.id}><td><strong>{r.orderNumber}</strong></td><td>{new Date(r.createdAt).toLocaleDateString('en-NG')}</td><td>{money(r.subtotalAmount)}</td><td>− {money(r.commissionAmount)}</td><td><strong>{money(r.vendorEarning)}</strong></td></tr>)}{!rows.length&&<Empty n={5} t="No delivered earnings in this period."/>}</tbody></table></div></section></div>}
function Transactions({rows}:any){return <div className="finance-content"><section className="finance-card"><Head s="Append-only ledger" t="Transactions"/><TransactionTable rows={rows}/></section></div>};function TransactionTable({rows}:any){return <div className="finance-table-wrap"><table className="finance-table"><thead><tr><th>Type</th><th>Description</th><th>Date</th><th>Amount</th></tr></thead><tbody>{rows.map((r:any)=><tr key={r.id}><td><span className="ledger-type">{r.type.replaceAll('_',' ')}</span></td><td>{r.description||'Ledger entry'}</td><td>{new Date(r.createdAt).toLocaleString('en-NG')}</td><td className={r.amount<0?'negative':'positive'}>{r.amount>0?'+ ':''}{money(r.amount)}</td></tr>)}{!rows.length&&<Empty n={4} t="No ledger transactions in this period."/>}</tbody></table></div>}
function Payouts({rows}:any){return <div className="finance-content"><section className="finance-card"><Head s="Settlement history" t="Payouts"/><div className="finance-table-wrap"><table className="finance-table"><thead><tr><th>Payout ID</th><th>Date</th><th>Amount</th><th>Bank</th><th>Status</th><th>Reference</th></tr></thead><tbody>{rows.map((r:any)=><tr key={r.id}><td><strong>{r.id.slice(0,8).toUpperCase()}</strong></td><td>{new Date(r.createdAt).toLocaleDateString('en-NG')}</td><td>{money(r.amount)}</td><td>{r.bankName||'—'} {r.accountNumberLast4&&<small className="table-sub">•••• {r.accountNumberLast4}</small>}</td><td><span className="finance-status good">{r.status}</span></td><td>{r.reference}</td></tr>)}{!rows.length&&<Empty n={6} t="No payouts have been recorded yet."/>}</tbody></table></div></section></div>}
function Account({a,f,setF,save,saving}:any){return <div className="finance-content"><div className="finance-grid-2"><section className="finance-card"><Head s="Connected payout method" t={a?.bankName||'Add bank account'}/>{a?<div className="account-detail"><div><span>Account name</span><strong>{a.accountName}</strong></div><div><span>Account number</span><strong>•••• •••• {a.accountNumberLast4}</strong></div><div><span>Status</span><strong>{a.status}</strong></div><p>ROZZI stores only the last four digits in this dashboard record. Provider-side verification can be connected when payout credentials are configured.</p></div>:<p className="finance-muted">No payout account is connected yet.</p>}</section><section className="finance-card"><Head s="Bank details" t={a?'Update account':'Connect an account'}/><form className="finance-form" onSubmit={save}><label>Bank name<input value={f.bankName} onChange={(e:any)=>setF({...f,bankName:e.target.value})} required placeholder="e.g. GTBank"/></label><label>Bank code<input value={f.bankCode} onChange={(e:any)=>setF({...f,bankCode:e.target.value})} placeholder="Optional"/></label><label>Account name<input value={f.accountName} onChange={(e:any)=>setF({...f,accountName:e.target.value})} required placeholder="Name on account"/></label><label>10-digit account number<input value={f.accountNumber} onChange={(e:any)=>setF({...f,accountNumber:e.target.value.replace(/\D/g,'').slice(0,10)})} required inputMode="numeric" placeholder="0123456789"/></label><button className="finance-primary" disabled={saving}>{saving?'Saving…':a?'Update payout account':'Save payout account'}</button></form></section></div></div>};function Empty({n,t}:{n:number;t:string}){return <tr><td colSpan={n}><div className="finance-empty">{t}</div></td></tr>}
